def count_prime_numbers(n):
    """Count the number of prime numbers less than n.

    Args:
    Returns:
    """
    ctr = 0
    for num in range(n):
        if num <= 2:
            continue
        for i in range(2, num):
            if (num % i) == 0:
                break
        else:
            ctr += 1
    return ctr

